const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, HeadingLevel, BorderStyle, WidthType, ShadingType,
  LevelFormat, PageNumber, Header, Footer, TabStopType, TabStopPosition,
  VerticalAlign
} = require('docx');
const fs = require('fs');

// Brand colors
const LUXORA_GOLD = "C9A84C";
const LUXORA_DARK = "1A1A2E";
const LUXORA_LIGHT = "F9F6F0";
const ACORN_GREEN = "2D5A27";
const LIGHT_GRAY = "F2F2F2";
const MID_GRAY = "E0E0E0";
const TEXT_DARK = "2C2C2C";
const TEXT_MED = "555555";

const border = { style: BorderStyle.SINGLE, size: 1, color: "DDDDDD" };
const borders = { top: border, bottom: border, left: border, right: border };
const noBorders = {
  top: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
  bottom: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
  left: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
  right: { style: BorderStyle.NONE, size: 0, color: "FFFFFF" },
};

function spacer(pts = 100) {
  return new Paragraph({ children: [new TextRun("")], spacing: { before: pts, after: pts } });
}

function sectionHeader(text, color = LUXORA_DARK) {
  return new Paragraph({
    children: [new TextRun({ text, bold: true, size: 26, color, font: "Arial" })],
    spacing: { before: 280, after: 120 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: LUXORA_GOLD, space: 4 } }
  });
}

function bodyText(text, bold = false, italic = false) {
  return new Paragraph({
    children: [new TextRun({ text, bold, italic, size: 22, color: TEXT_DARK, font: "Arial" })],
    spacing: { before: 60, after: 60 }
  });
}

function bulletItem(text) {
  return new Paragraph({
    numbering: { reference: "bullets", level: 0 },
    children: [new TextRun({ text, size: 22, color: TEXT_DARK, font: "Arial" })],
    spacing: { before: 60, after: 60 }
  });
}

function twoColRow(label, value, shaded = false) {
  return new TableRow({
    children: [
      new TableCell({
        borders,
        width: { size: 3200, type: WidthType.DXA },
        shading: shaded ? { fill: LIGHT_GRAY, type: ShadingType.CLEAR } : { fill: "FFFFFF", type: ShadingType.CLEAR },
        margins: { top: 100, bottom: 100, left: 140, right: 140 },
        children: [new Paragraph({ children: [new TextRun({ text: label, bold: true, size: 20, color: TEXT_DARK, font: "Arial" })] })]
      }),
      new TableCell({
        borders,
        width: { size: 6160, type: WidthType.DXA },
        shading: shaded ? { fill: LIGHT_GRAY, type: ShadingType.CLEAR } : { fill: "FFFFFF", type: ShadingType.CLEAR },
        margins: { top: 100, bottom: 100, left: 140, right: 140 },
        children: [new Paragraph({ children: [new TextRun({ text: value, size: 20, color: TEXT_MED, font: "Arial" })] })]
      }),
    ]
  });
}

const doc = new Document({
  numbering: {
    config: [
      {
        reference: "bullets",
        levels: [{
          level: 0, format: LevelFormat.BULLET, text: "\u2022", alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 720, hanging: 360 } } }
        }]
      }
    ]
  },
  styles: {
    default: { document: { run: { font: "Arial", size: 22, color: TEXT_DARK } } },
    paragraphStyles: [
      {
        id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 40, bold: true, font: "Arial", color: LUXORA_DARK },
        paragraph: { spacing: { before: 240, after: 120 }, outlineLevel: 0 }
      },
      {
        id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 28, bold: true, font: "Arial", color: LUXORA_DARK },
        paragraph: { spacing: { before: 200, after: 100 }, outlineLevel: 1 }
      }
    ]
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1080, right: 1260, bottom: 1080, left: 1260 }
      }
    },
    headers: {
      default: new Header({
        children: [
          new Paragraph({
            children: [
              new TextRun({ text: "PARTNERSHIP PROPOSAL", bold: true, size: 18, color: TEXT_MED, font: "Arial" }),
              new TextRun({ text: "   |   Confidential", size: 18, color: TEXT_MED, font: "Arial", italics: true }),
            ],
            border: { bottom: { style: BorderStyle.SINGLE, size: 4, color: LUXORA_GOLD, space: 4 } },
            spacing: { after: 120 }
          })
        ]
      })
    },
    footers: {
      default: new Footer({
        children: [
          new Paragraph({
            children: [
              new TextRun({ text: "The Luxora Collective  |  theluxoracollective.co  |  Confidential", size: 16, color: TEXT_MED, font: "Arial" })
            ],
            border: { top: { style: BorderStyle.SINGLE, size: 4, color: LUXORA_GOLD, space: 4 } },
            alignment: AlignmentType.CENTER,
            spacing: { before: 120 }
          })
        ]
      })
    },
    children: [

      // TITLE BLOCK
      spacer(80),
      new Paragraph({
        children: [
          new TextRun({ text: "Partnership Proposal", bold: true, size: 52, color: LUXORA_DARK, font: "Arial" })
        ],
        spacing: { before: 0, after: 60 }
      }),
      new Paragraph({
        children: [
          new TextRun({ text: "Acorn Biolabs  +  The Luxora Collective", size: 32, color: LUXORA_GOLD, font: "Arial", bold: true })
        ],
        spacing: { before: 0, after: 60 }
      }),
      new Paragraph({
        children: [
          new TextRun({ text: "A Referral and Co-Marketing Framework for Independent MedSpa Growth", size: 22, color: TEXT_MED, font: "Arial", italics: true })
        ],
        spacing: { before: 0, after: 300 }
      }),

      // OVERVIEW TABLE
      new Table({
        width: { size: 9360, type: WidthType.DXA },
        columnWidths: [4680, 4680],
        rows: [
          new TableRow({
            children: [
              new TableCell({
                borders,
                width: { size: 4680, type: WidthType.DXA },
                shading: { fill: LUXORA_DARK, type: ShadingType.CLEAR },
                margins: { top: 200, bottom: 200, left: 200, right: 200 },
                verticalAlign: VerticalAlign.CENTER,
                children: [
                  new Paragraph({ children: [new TextRun({ text: "Acorn Biolabs", bold: true, size: 26, color: "FFFFFF", font: "Arial" })], alignment: AlignmentType.CENTER }),
                  new Paragraph({ children: [new TextRun({ text: "Stem Cell Banking + Secretome Treatments", size: 18, color: "CCCCCC", font: "Arial" })], alignment: AlignmentType.CENTER, spacing: { before: 60 } })
                ]
              }),
              new TableCell({
                borders,
                width: { size: 4680, type: WidthType.DXA },
                shading: { fill: LUXORA_GOLD, type: ShadingType.CLEAR },
                margins: { top: 200, bottom: 200, left: 200, right: 200 },
                verticalAlign: VerticalAlign.CENTER,
                children: [
                  new Paragraph({ children: [new TextRun({ text: "The Luxora Collective", bold: true, size: 26, color: "FFFFFF", font: "Arial" })], alignment: AlignmentType.CENTER }),
                  new Paragraph({ children: [new TextRun({ text: "MedSpa Revenue Growth Consultancy", size: 18, color: "FFFFFF", font: "Arial" })], alignment: AlignmentType.CENTER, spacing: { before: 60 } })
                ]
              })
            ]
          })
        ]
      }),

      spacer(200),

      // WHO WE ARE
      sectionHeader("Who We Are"),
      spacer(60),

      new Table({
        width: { size: 9360, type: WidthType.DXA },
        columnWidths: [4580, 200, 4580],
        rows: [
          new TableRow({
            children: [
              new TableCell({
                borders: noBorders,
                width: { size: 4580, type: WidthType.DXA },
                shading: { fill: LIGHT_GRAY, type: ShadingType.CLEAR },
                margins: { top: 160, bottom: 160, left: 180, right: 180 },
                children: [
                  new Paragraph({ children: [new TextRun({ text: "The Luxora Collective", bold: true, size: 22, color: LUXORA_DARK, font: "Arial" })], spacing: { after: 80 } }),
                  new Paragraph({ children: [new TextRun({ text: "We are a B2B growth consultancy built exclusively for independent and small-group medspas generating $500K to $3M annually. Our flagship program, the 90-Day Growth Engine, does one thing: find and activate the revenue that already exists inside a medspa.", size: 20, color: TEXT_DARK, font: "Arial" })], spacing: { after: 100 } }),
                  new Paragraph({ children: [new TextRun({ text: "We install membership programs, package architecture, upsell frameworks, AI-powered follow-up, and staff training. The result is more lifetime clients, more recurring revenue, and less dependence on ad spend.", size: 20, color: TEXT_DARK, font: "Arial" }) ]}),
                ]
              }),
              new TableCell({ borders: noBorders, width: { size: 200, type: WidthType.DXA }, children: [new Paragraph({ children: [] })] }),
              new TableCell({
                borders: noBorders,
                width: { size: 4580, type: WidthType.DXA },
                shading: { fill: LIGHT_GRAY, type: ShadingType.CLEAR },
                margins: { top: 160, bottom: 160, left: 180, right: 180 },
                children: [
                  new Paragraph({ children: [new TextRun({ text: "Acorn Biolabs", bold: true, size: 22, color: LUXORA_DARK, font: "Arial" })], spacing: { after: 80 } }),
                  new Paragraph({ children: [new TextRun({ text: "Acorn is the first personalized regenerative medicine company focused on non-invasive stem cell collection from hair follicles. Their flagship offering gives patients a way to bank their own stem cells today and use them in proprietary secretome treatments that outperform PRP with up to 34x the regenerative volume.", size: 20, color: TEXT_DARK, font: "Arial" })], spacing: { after: 100 } }),
                  new Paragraph({ children: [new TextRun({ text: "The product is autologous, clinically consistent, and deeply sticky: once a patient starts, they come back.", size: 20, color: TEXT_DARK, font: "Arial" }) ]}),
                ]
              })
            ]
          })
        ]
      }),

      spacer(200),

      // WHY THIS PARTNERSHIP MAKES SENSE
      sectionHeader("Why This Partnership Makes Sense"),
      spacer(80),
      bodyText("The Luxora Collective's entire focus is on converting new medspa clients into lifetime clients. Acorn's secretome product is one of the most compelling tools in the market for doing exactly that."),
      spacer(60),
      bodyText("Our clients are independent medspa owners who already serve an affluent, aesthetics-forward clientele. These are exactly the patients who will pay premium prices for a personalized, science-backed treatment they cannot get anywhere else."),
      spacer(60),
      bodyText("Integrating Acorn into our 90-Day Growth Engine gives our clients a differentiated service offering, a recurring revenue driver, and a reason for high-value patients to stay loyal. It also gives Acorn warm introductions to qualified, revenue-focused practice owners who are actively investing in their growth."),

      spacer(200),

      // WHAT WE ARE PROPOSING
      sectionHeader("What We Are Proposing"),
      spacer(80),
      bodyText("We are open to building this in whatever structure makes sense for your team. Below is where we would like to start the conversation:"),
      spacer(100),

      new Table({
        width: { size: 9360, type: WidthType.DXA },
        columnWidths: [3200, 6160],
        rows: [
          new TableRow({
            children: [
              new TableCell({
                borders: { top: border, bottom: border, left: border, right: border },
                width: { size: 3200, type: WidthType.DXA },
                shading: { fill: LUXORA_DARK, type: ShadingType.CLEAR },
                margins: { top: 100, bottom: 100, left: 140, right: 140 },
                children: [new Paragraph({ children: [new TextRun({ text: "Area", bold: true, size: 20, color: "FFFFFF", font: "Arial" })] })]
              }),
              new TableCell({
                borders: { top: border, bottom: border, left: border, right: border },
                width: { size: 6160, type: WidthType.DXA },
                shading: { fill: LUXORA_DARK, type: ShadingType.CLEAR },
                margins: { top: 100, bottom: 100, left: 140, right: 140 },
                children: [new Paragraph({ children: [new TextRun({ text: "Our Thinking", bold: true, size: 20, color: "FFFFFF", font: "Arial" })] })]
              })
            ]
          }),
          twoColRow("Preferred Partner Status", "Acorn Biolabs listed as a preferred partner on The Luxora Collective website and included in relevant client deliverables and recommendations.", false),
          twoColRow("Client Introductions", "When a Luxora client is a strong fit for Acorn, we make a warm, direct introduction. We are not blasting cold leads; we are connecting Acorn with practice owners already invested in retention and lifetime value.", true),
          twoColRow("Co-Marketing", "Shared social content, co-branded materials, and featured placement inside our marketing assets. Acorn already has a strong media kit. We want to integrate and amplify it.", false),
          twoColRow("Referral Compensation", "We are open to a structure that compensates both sides for referred clients who convert. We see this as a two-way relationship: if Acorn encounters a medspa that needs a growth system, we want to be the name they hear.", true),
          twoColRow("Overlap Protection", "We are happy to work with your team on a simple process to flag any accounts we may both already be in conversation with, so we are moving in the same direction.", false),
          twoColRow("Program Integration", "We want to include Acorn as a recommended add-on inside the 90-Day Growth Engine. Not as a hard sell, but as an example of a genuinely differentiated, high-retention service our clients should know about.", true),
        ]
      }),

      spacer(200),

      // WHAT WE ARE NOT
      sectionHeader("What This Is Not"),
      spacer(60),
      bulletItem("This is not an exclusive arrangement. We understand Acorn works with many practice types and partners."),
      bulletItem("This is not a request for product discounts or subsidized kits. We want Acorn at full value so practices see it as the premium offering it is."),
      bulletItem("This is not a one-way referral agreement. We genuinely want to add value to Acorn's pipeline the same way we are asking Acorn to add value to ours."),

      spacer(200),

      // NEXT STEPS
      sectionHeader("Suggested Next Steps"),
      spacer(60),
      bodyText("We want to keep this simple. Here is what we are proposing as a starting point:"),
      spacer(80),
      new Paragraph({
        numbering: { reference: "bullets", level: 0 },
        children: [new TextRun({ text: "A 30-minute call between your head of sales and our team to align on structure, overlap protection, and any internal approvals needed.", size: 22, color: TEXT_DARK, font: "Arial" })],
        spacing: { before: 80, after: 80 }
      }),
      new Paragraph({
        numbering: { reference: "bullets", level: 0 },
        children: [new TextRun({ text: "A simple one-page agreement outlining referral terms, co-marketing expectations, and the overlap process. Nothing complicated.", size: 22, color: TEXT_DARK, font: "Arial" })],
        spacing: { before: 80, after: 80 }
      }),
      new Paragraph({
        numbering: { reference: "bullets", level: 0 },
        children: [new TextRun({ text: "A test run: one warm client introduction from our side within the first 30 days so both teams can see how this works in practice.", size: 22, color: TEXT_DARK, font: "Arial" })],
        spacing: { before: 80, after: 80 }
      }),

      spacer(200),

      // CONTACT
      new Table({
        width: { size: 9360, type: WidthType.DXA },
        columnWidths: [9360],
        rows: [
          new TableRow({
            children: [
              new TableCell({
                borders,
                width: { size: 9360, type: WidthType.DXA },
                shading: { fill: LUXORA_GOLD, type: ShadingType.CLEAR },
                margins: { top: 200, bottom: 200, left: 300, right: 300 },
                children: [
                  new Paragraph({ children: [new TextRun({ text: "Let's Build This Together", bold: true, size: 28, color: "FFFFFF", font: "Arial" })], alignment: AlignmentType.CENTER, spacing: { after: 80 } }),
                  new Paragraph({ children: [new TextRun({ text: "Bethany Anne, Co-Founder & CEO", size: 22, color: "FFFFFF", font: "Arial" })], alignment: AlignmentType.CENTER, spacing: { after: 40 } }),
                  new Paragraph({ children: [new TextRun({ text: "The Luxora Collective  |  theluxoracollective.co", size: 22, color: "FFFFFF", font: "Arial" })], alignment: AlignmentType.CENTER }),
                ]
              })
            ]
          })
        ]
      }),

      spacer(100),

    ]
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync("/home/claude/Luxora_Acorn_Partnership_Proposal.docx", buffer);
  console.log("Done");
});

